def main():
    out = os.path.dirname(os.path.abspath(__file__))
    random.Random(42).shuffle(QA)
    train, ev = [], []
    for i, (topic, q, a) in enumerate(QA):
        rec = {"messages": [{"role": "system", "content": SYSTEM},
                            {"role": "user", "content": q},
                            {"role": "assistant", "content": a}],
               "meta": {"thema": topic}}
        (ev if i % 8 == 7 else train).append(rec)
    for name, recs in (("train.jsonl", train), ("eval.jsonl", ev)):
        with open(os.path.join(out, name), "w", encoding="utf-8") as f:
            for r in recs:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")
    from collections import Counter
    print(len(QA), "Paare:", len(train), "train,", len(ev), "eval;", dict(Counter(t for t, _, _ in QA)))

if __name__ == "__main__":
    main()
